// ============================================================================
// Cached kernel entry — one per unique (op, shape, dtype) tuple
// ============================================================================

enum xdna_op_kind : int {
    XDNA_OP_GEMM               = 0,  // M>=32 prefill MUL_MAT via IRON GEMM
    XDNA_OP_GEMV               = 1,  // M==1  decode  MUL_MAT via IRON GEMV
    XDNA_OP_SWIGLU_DECODE      = 2,  // M==1  fused SwiGLU FFN (gate/up/down + SiLU + mul)
    XDNA_OP_SWIGLU_PREFILL     = 3,  // M>=32 fused SwiGLU FFN (gate/up/down + SiLU + mul)
    XDNA_OP_SWIGLU_DECODE_INT8 = 4,  // M==1  W8A16 fused SwiGLU FFN (int8 weights, bf16 acts)
    XDNA_OP_SWIGLU_FUSED_INT8  = 5,  // M==1  fused gate+up+silu+mul INT8 + standalone down GEMV
    XDNA_OP_SWIGLU_PREFILL_INT8 = 6,  // M>=32 W8A8 INT8 SwiGLU FFN (both weights and activations int8)
    XDNA_OP_QKV = 7,  // M==1 fused Q/K/V (single GEMV with concatenated weights)
    XDNA_OP_RMS_NORM            = 8,  // standalone RMSNorm (bf16, eps=1e-5 baked-in)
    XDNA_OP_ATTENTION_PREFILL   = 9,  // chained attention block (RMSNorm+QKV+RoPE+MHA+O+residual)
    XDNA_OP_GEMV_INT4           = 10, // M==1  fused INT4-dequant + GEMV (Q4_0 weights, bf16 acts)
    XDNA_OP_SWIGLU_DECODE_INT4  = 11, // M==1  W4A16 fused SwiGLU FFN (Q4_0 weights, bf16 acts; Phase 8.2)
    XDNA_OP_GEMV_INT4_BATCH     = 12, // M=2..8 fused INT4-dequant + batched GEMV (spec-dec verify)
    XDNA_OP_FFN16_2MM           = 13, // M==1 16-tile fused FFN (gate+up+silu+mul+down) single dispatch
    XDNA_OP_QKV16               = 14, // M==1 16-tile fused QKV projection (Q+K+V concat) single dispatch
    XDNA_OP_DECODE_FRONT_ATTN   = 15, // M==1 fused front half (Q-GEMV + interleaved RoPE + flowkv attn) #32
    XDNA_OP_DECODE_BACK_MONO    = 16, // M==1 fused back half (O-proj + residual + RMSNorm + mono-FFN) #32
    XDNA_OP_DECODE_LAYER_F3BEST = 17, // M==1 full fused decode layer (attn + O-proj + FFN) one dispatch (F3-best)
};

// Phase 9: per-entry input/output BO ring for async dispatch. Each call
// to a dispatch fn picks the next slot (round-robin); the slot's previous
// run is waited on (if any) before the new memcpy overwrites the input.
// Q_max=4 covers ~1 attention-cycle worth of in-flight ops on Llama 3.2
// 1B (q+k+v+o ≈ 4 dispatches). Memory cost per entry = 4 * (K + N) * 2
// bytes, typical ~80KB.
static constexpr int XDNA_PHASE9_RING_SIZE = 4;

struct xdna_f3best_kv_cache {
    std::unique_ptr<xrt::bo> bo;
    int64_t last_n_kv = 0;
    const void * last_k_data = nullptr;
    const void * last_v_data = nullptr;
    uint64_t last_prefix_hash = 0;
};

struct xdna_kernel_entry {
    xdna_op_kind  op_kind;
    xrt::xclbin   xclbin;
    xrt::hw_context hw_ctx;
    xrt::kernel   kernel;
    std::vector<char> insts;
    xrt::bo       insts_bo;
    int64_t       M, K, N;
    // Persistent per-call BOs. Shape is fixed by (M,K,N) for this kernel,
    // so we allocate once and memcpy new data in per call.
    // unique_ptr defers construction until first use (needs kernel group_id).
    // GEMM: a_bo = activation (M*K bf16), c_bo = output (M*N bf16)
    // GEMV: a_bo = vector activation (K bf16), c_bo = output (N bf16)
    //
    // LEGACY single-slot BOs. Kept for non-Phase-9 dispatch paths (bf16
    // GEMV/GEMM, INT4 prefill, etc.) that still use the synchronous
    // wait-per-op pattern. Phase 9 INT4 GEMV dispatch uses the ring below.
    std::unique_ptr<xrt::bo> a_bo;
    std::unique_ptr<xrt::bo> c_bo;
    // FFN16_2MM extra BOs: O(out)/W via a_bo-pattern + 2 dummy (D3,D4).
    std::unique_ptr<xrt::bo> d3_bo;
    std::unique_ptr<xrt::bo> d4_bo;
    // #245: tapped debug-build (F3BEST_ATTN_DUMP). The relay (rl) tile copies its
    // pre-O-proj attn_out (E bf16) into this host-visible BO via the rl tile's free
    // MM2S ch1 + sh2 S2MM ch0. Only allocated/bound when the _attnout xclbin (9-arg
    // kernel) is active; nullptr on the production 8-arg path.
    std::unique_ptr<xrt::bo> tap_bo;
    // Phase 9 per-call BO ring. Indexed 0..XDNA_PHASE9_RING_SIZE-1.
    // The ring's per-slot run + deferred lambda live in the context-level
    // inflight tracker (xdna_inflight_tracker), keyed by slot_dst_data[i].
    // slot_active[i] is a back-pressure guard: dispatch picks next_slot,
    // and if active, calls inflight.wait_for(slot_dst_data[slot]) so the
    // previous slot owner's deferred completion (bias compensation +
    // write to tensor->data) runs BEFORE the new memcpy overwrites the
    // input BO. The lambda clears slot_active[i] as a side effect.
    std::unique_ptr<xrt::bo> a_bo_ring[XDNA_PHASE9_RING_SIZE];
    std::unique_ptr<xrt::bo> c_bo_ring[XDNA_PHASE9_RING_SIZE];
    bool                     slot_active[XDNA_PHASE9_RING_SIZE] = {};
    void *                   slot_dst_data[XDNA_PHASE9_RING_SIZE] = {};
    int                      next_slot = 0;
    // Cache of per-weight-pointer bf16 weight buffers keyed by src0->data.
    // Weights are immutable after load, so we convert+DMA once and reuse.
    // GEMM: transposed to [K,N] row-major. GEMV: native [N,K] row-major.
    std::unordered_map<const void *, xrt::bo> b_bo_cache;
    std::unique_ptr<std::mutex> b_bo_mutex = std::make_unique<std::mutex>();
    // #35: cached xrt::run PER LAYER (keyed by weight-data ptr, like b_bo_cache).
    // The FIRST start() of a (run+bound-args) config pays a ~2ms one-time setup;
    // re-starting the SAME run with the SAME args is warm (~1.1ms vs 3.3ms, WARM2).
    // set_arg is done ONCE at creation; reuse just re-syncs BO contents + start, so
    // every layer is warm from token 2 on (token 1 pays the 16 one-time setups).
    std::unordered_map<const void *, std::unique_ptr<xrt::run>> run_cache_map;
    // #79: per-layer packed-KV BO cache for f3best. The xclbin sees the same
    // arg7 layout, but steady decode appends only new K/V slots instead of
    // re-packing the full 256-token window for every layer and token.
    std::unordered_map<const void *, xdna_f3best_kv_cache> f3best_kv_cache_map;
    // #35 sub-buffer experiment (XDNA_F3BEST_SUBBUF): ONE big parent weight BO
    // holds every layer's weight slot; each layer binds a sub-buffer at its slot
    // offset to arg5 (contents = that layer's packed weights). Tests whether a
    // sub-buffer at a per-layer offset keeps the weight-DMA config WARM (~1.1ms)
    // vs a distinct per-layer BO which re-primes the shim DMA cold (~3.15ms).
    // Memory cost is identical to the per-layer path (16 slots vs 16 BOs = 528MB).
    std::unique_ptr<xrt::bo> parent_weight_bo;
    int weight_slot_next = 0;
    // #35 isolation probe (XDNA_F3BEST_ONEBO): bind ONE shared weight BO for ALL
    // 16 layers (wrong weights → garbage output, timing-only). Tests whether
    // BO-IDENTITY alone keeps the weight-DMA warm; decides if DDR_PATCH-into-one-BO
    // (which keeps arg5 constant + patches the offset in insts) can reach ~1.1ms.
    std::unique_ptr<xrt::bo> shared_weight_bo;
    // #35 (XDNA_F3BEST_ONERUN): ONE run object reused across ALL 16 layers, re-set_arg(5)
    // per layer (c/a/d4 BOs are shared → bound once). WARM2 proved warmth is tied to
    // repeating the SAME run object; this tests whether re-patching one run in place keeps
    // every layer warm (the reachable ~30 t/s path if BO-switch is not the cold cause).
    std::unique_ptr<xrt::run> shared_run;
    // DDR_PATCH mode (XDNA_F3BEST_DDR_PATCH): ONE unified weight BO for all
    // 16 layers, with per-layer txn offset patching. Keeps arg5 constant (BO
    // identity) while patching per-layer offset in the insts DDR_PATCH ops.
    std::unique_ptr<xrt::bo> unified_weight_bo;
    // DDR_PATCH: ONE run object reused across ALL 16 layers. Arg 7 (KV) is
    // rebound per layer; all other args (including weight BO) are constant.
    std::unique_ptr<xrt::run> f3best_unified_run;
    std::unordered_map<const void*, int> f3best_layer_slot;
    std::vector<char> txn_template;
    int f3best_layer_count = 0;
    bool f3best_ddr_patch_ready = false;
};

// ---------------------------------------------------------------------------
// Step 2d-δ profiling spike — per-dispatch / per-token timing sink.
// Gate: XDNA_PROFILE_DISPATCHES=1.  Output: CSV at XDNA_PROFILE_DISPATCHES_PATH
// (default xdna_profile_<pid>.csv). Token cap: XDNA_PROFILE_MAX_TOKENS=32.
// Defined here (early in TU) so the RAII timer is visible at all dispatch
// sites that consume it (the earliest one is around line 2370).
// ---------------------------------------------------------------------------

struct xdna_profile_row {
    int64_t      token_idx;
    int          layer_idx;
    const char * kernel;
    int64_t      submit_us;
    int64_t      wait_us;
    int64_t      sync_pre_us;
    int64_t      sync_post_us;
    int64_t      host_pre_us;
    int64_t      host_post_us;
};

struct xdna_profile_sink {
    bool                          enabled       = false;
    std::mutex                    mu;
    std::vector<xdna_profile_row> rows;
    int64_t                       token_idx     = 0;
    int64_t                       max_tokens    = 32;
    std::string                   path;
    std::chrono::steady_clock::time_point  token_start;
    int                                    token_dispatch_count = 0;
    int64_t                                token_npu_us         = 0;
    int64_t                                token_sync_us        = 0;
    int64_t                                token_host_us        = 0;
    bool                                   flushed              = false;

    static xdna_profile_sink & get() {
        static xdna_profile_sink inst;
        static std::once_flag init_flag;
        std::call_once(init_flag, [] {
            xdna_profile_sink & s = inst;
            s.enabled = xdna_env_enabled("XDNA_PROFILE_DISPATCHES");
            const char * mt = getenv("XDNA_PROFILE_MAX_TOKENS");
            if (mt && *mt) {
                s.max_tokens = strtoll(mt, NULL, 10);
                if (s.max_tokens <= 0) s.max_tokens = 32;
            }
            const char * p = getenv("XDNA_PROFILE_DISPATCHES_PATH");
            if (p && *p) {
                s.path = p;
            } else {
                char buf[64];
                snprintf(buf, sizeof(buf), "xdna_profile_%u.csv",
                         (unsigned)GetCurrentProcessId());
                s.path = buf;
            }
            if (s.enabled) {
                fprintf(stderr,
                    "ggml-xdna: [PROFILE] dispatches enabled, "
                    "max_tokens=%lld path=%s\n",
                    (long long)s.max_tokens, s.path.c_str());
            }
        });
        return inst;
    }

    void push(const xdna_profile_row & r) {
        if (!enabled) return;
        std::lock_guard<std::mutex> lk(mu);
        if ((int64_t)rows.size() > max_tokens * 256) return;
        rows.push_back(r);
        token_dispatch_count++;
        token_npu_us  += r.submit_us + r.wait_us;
        token_sync_us += r.sync_pre_us + r.sync_post_us;
        token_host_us += r.host_pre_us + r.host_post_us;
    }

    void note_token_start() {
        if (!enabled) return;
        std::lock_guard<std::mutex> lk(mu);
        token_start          = std::chrono::steady_clock::now();
        token_dispatch_count = 0;
        token_npu_us         = 0;
        token_sync_us        = 0;
        token_host_us        = 0;
    }

    void note_token_end() {
        if (!enabled) return;
        std::lock_guard<std::mutex> lk(mu);
        const auto now = std::chrono::steady_clock::now();
        const int64_t total_us = std::chrono::duration_cast<std::chrono::microseconds>(
            now - token_start).count();
        xdna_profile_row tk;
        tk.token_idx    = token_idx;
        tk.layer_idx    = -1;
        tk.kernel       = "_TOKEN";
        tk.submit_us    = total_us;
        tk.wait_us      = token_dispatch_count;
        tk.sync_pre_us  = token_npu_us;
        tk.sync_post_us = token_sync_us;
        tk.host_pre_us  = token_host_us;
        tk.host_post_us = 0;
        rows.push_back(tk);
        token_idx++;
        if (token_idx >= max_tokens && !flushed) {
            flush_csv_unlocked();
            flushed = true;
            fprintf(stderr,
                "ggml-xdna: [PROFILE] flushed %lld tokens to %s\n",
                (long long)token_idx, path.c_str());
        }
    }

    ~xdna_profile_sink() {
        if (enabled && !flushed && !rows.empty()) {
            flush_csv_unlocked();
            fprintf(stderr,
                "ggml-xdna: [PROFILE] flushed at exit (%lld tokens) to %s\n",
                (long long)token_idx, path.c_str());
        }
    }

    void flush_csv_unlocked() {
        FILE * f = fopen(path.c_str(), "w");
        if (!f) {
            fprintf(stderr,
                "ggml-xdna: [PROFILE] could not open %s for writing\n",
                path.c_str());
            return;
        }
        fprintf(f, "# _TOKEN row schema: submit_us=total_us "
                   "wait_us=dispatch_count sync_pre_us=npu_us "
                   "sync_post_us=sync_us host_pre_us=host_us host_post_us=0\n");
        fprintf(f, "token_idx,layer_idx,kernel,submit_us,wait_us,"
                   "sync_pre_us,sync_post_us,host_pre_us,host_post_us\n");
        for (const auto & r : rows) {
            fprintf(f, "%lld,%d,%s,%lld,%lld,%lld,%lld,%lld,%lld\n",
                    (long long)r.token_idx, r.layer_idx, r.kernel,
                    (long long)r.submit_us,    (long long)r.wait_us,
                    (long long)r.sync_pre_us,  (long long)r.sync_post_us,
                    (long long)r.host_pre_us,  (long long)r.host_post_us);
        }
        fclose(f);
    }
};

struct xdna_dispatch_timer {
    bool         enabled;
    const char * kernel;
    int          layer_idx;
    using clk = std::chrono::steady_clock;
    clk::time_point t0, t_sync_pre, t_submit, t_wait, t_sync_post;
    int64_t host_pre_us  = 0;
    int64_t host_post_us = 0;
    bool finalized = false;

    explicit xdna_dispatch_timer(const char * k, int layer = -1)
        : enabled(xdna_profile_sink::get().enabled),
          kernel(k), layer_idx(layer) {
        if (!enabled) return;
        t0 = t_sync_pre = t_submit = t_wait = t_sync_post = clk::now();
    }

    void mark_sync_pre_done() {
        if (!enabled) return;
        t_sync_pre = clk::now();
    }
    void mark_submit_done() {
        if (!enabled) return;
        t_submit = clk::now();
    }
    void mark_wait_done() {
        if (!enabled) return;
        t_wait = clk::now();
    }
    void mark_sync_post_done() {
        if (!enabled) return;
        t_sync_post = clk::now();
    }
    void add_host_pre_us(int64_t us) { host_pre_us  += us; }
    void add_host_post_us(int64_t us) { host_post_us += us; }

    ~xdna_dispatch_timer() {
        if (!enabled || finalized) return;
        finalized = true;
        if (t_sync_post.time_since_epoch().count() <
                t_wait.time_since_epoch().count()) {
            t_sync_post = t_wait;
        }
        auto us = [](clk::time_point a, clk::time_point b) {
            return std::chrono::duration_cast<std::chrono::microseconds>(b - a).count();
        };
        xdna_profile_row r;
        r.token_idx     = xdna_profile_sink::get().token_idx;
        r.layer_idx     = layer_idx;
        r.kernel        = kernel;
        r.sync_pre_us   = us(t0,         t_sync_pre);
        r.submit_us     = us(t_sync_pre, t_submit);
        r.wait_us       = us(t_submit,   t_wait);
        r.sync_post_us  = us(t_wait,     t_sync_post);
        r.host_pre_us   = host_pre_us;
        r.host_post_us  = host_post_us;
        xdna_profile_sink::get().push(r);
    }
};

// ---------------------------------------------------------------------------
// Per-dispatch HOST submit-latency breakdown (Phase 0 #35 overhead probe).
// Gate: XDNA_DEBUG_SUBMIT_BREAKDOWN=1. Attributes the ~2ms steady-state host
// "submit" time into 3 phases so we know WHICH op to optimize before touching
// anything: KEY = make_cache_key + ensure_compiled (disk I/O!) + get_or_load;
// PREP = activation pack + bo::sync(TO_DEVICE) + weight-cache lookup;
// SUB = entry->kernel(...) run construction + XRT submit. Prints a rolling
// average every 200 calls per kernel name. Pure measurement, no behavior change.
// ---------------------------------------------------------------------------
struct xdna_submit_breakdown {
    int64_t n = 0, key_us = 0, prep_us = 0, sub_us = 0, wait_us = 0, sync_us = 0;
    int64_t pk = 0, pprep = 0, psub = 0, pwait = 0, psync = 0;   // prev cumulative (for incremental)
    static bool on() {
        static const bool e = xdna_env_enabled("XDNA_DEBUG_SUBMIT_BREAKDOWN");
        return e;
    }
    static std::unordered_map<std::string, xdna_submit_breakdown> & store() {
        static std::unordered_map<std::string, xdna_submit_breakdown> m;
        return m;
    }
    // wait/sync optional (host-only sites pass 0). Prints BOTH cumulative-avg
    // and the incremental delta-avg over the last 200 calls (the true
    // steady-state, since cumulative is polluted by warmup).
    static void add(const char * k, int64_t key, int64_t prep, int64_t sub,
                    int64_t wait = 0, int64_t sync = 0) {
        if (!on()) return;
        auto & a = store()[k];
        a.n++; a.key_us += key; a.prep_us += prep; a.sub_us += sub;
        a.wait_us += wait; a.sync_us += sync;
        static const int64_t period = []() {
            const char * p = getenv("XDNA_DEBUG_SUBMIT_BD_PERIOD");
            int64_t v = (p && *p) ? strtoll(p, NULL, 10) : 200;
            return v > 0 ? v : 200;
        }();
        if (a.n % period == 0) {
            const double d = (double)period;
            fprintf(stderr,
                "ggml-xdna: [SUBMIT-BD] %-16s n=%lld STEADY(last200,us): key=%.1f prep=%.1f submit=%.1f wait=%.1f sync=%.1f host=%.1f full=%.1f\n",
                k, (long long)a.n,
                (a.key_us - a.pk) / d, (a.prep_us - a.pprep) / d,
                (a.sub_us - a.psub) / d, (a.wait_us - a.pwait) / d,
                (a.sync_us - a.psync) / d,
                (a.key_us - a.pk + a.prep_us - a.pprep + a.sub_us - a.psub) / d,
                (a.key_us - a.pk + a.prep_us - a.pprep + a.sub_us - a.psub
                 + a.wait_us - a.pwait + a.sync_us - a.psync) / d);
            fflush(stderr);
            a.pk = a.key_us; a.pprep = a.prep_us; a.psub = a.sub_us;
            a.pwait = a.wait_us; a.psync = a.sync_us;
        }
    }
};

// Phase 9: backend-wide tracker of in-flight async dispatches. Each
// entry holds a wait_fn that blocks until the underlying NPU work is
// complete (this can wrap xrt::run::wait2() for single runs, or
// xrt::runlist::wait() for chained dispatches like SwiGLU INT4), plus
// a deferred lambda that completes the operation host-side (e.g. bias
// compensation). The dispatch function returns immediately after
// submitting + pushing here; the next consumer of the output tensor
// (or graph_compute end) drains.
//
// dst_data is the ggml tensor->data pointer the work writes to -- used
// to match wait_for(consumer_input) requests across the queue.
struct xdna_inflight_entry {
    std::function<void()>          wait_fn;   // wraps run.wait2() or runlist.wait()
    void *                         dst_data = nullptr;
    std::function<void()>          deferred;  // bias compensation, etc.
};

struct xdna_inflight_tracker {
    std::deque<xdna_inflight_entry> q;
    size_t Q_max = XDNA_PHASE9_RING_SIZE;

    // Wait until queue depth is below Q_max (pop+complete oldest if not),
    // then enqueue the new entry.
    void submit(std::function<void()> wait_fn, void * dst_data,
                std::function<void()> deferred) {
        while (q.size() >= Q_max) {
            pop_front_complete();
        }
        q.push_back(xdna_inflight_entry{std::move(wait_fn), dst_data,
                                         std::move(deferred)});
    }

    // Pop and complete entries that produce data_ptr. Typically called
    // before a consumer reads tensor->data on host.
    void wait_for(const void * data_ptr) {
        // The producer may not be at the head, but in practice ggml
        // graphs run in topological order so the latest write to a
        // given pointer is the most recent producer in q. Walk forward.
        for (auto it = q.begin(); it != q.end(); ) {
            if (it->dst_data == data_ptr) {
                if (it->wait_fn) it->wait_fn();
                if (it->deferred) it->deferred();
                it = q.erase(it);
            } else {
                ++it;
            }
        }
    }

    // Drain all pending entries. Called at the end of graph_compute.
    void drain() {
        while (!q.empty()) pop_front_complete();
    }

private:
    void pop_front_complete() {
        auto & e = q.front();
        if (e.wait_fn) e.wait_fn();
        if (e.deferred) e.deferred();
        q.pop_front();
    }
};

// ============================================================================
// Fused SwiGLU FFN kernel entry — one chained xclbin, 4 sub-kernels
// ============================================================================

// Sub-kernel slot indices into the chained SwiGLU xclbin.
//
// IRON-windows uses different kernel counts per path:
//   - Decode bf16: 2 kernels (fused gate+up+silu+mul, down GEMV)
//   - Prefill bf16: 3 kernels (gemm_1, silu_mul, gemm_2)
//   - Decode INT8: NOT AVAILABLE in IRON-windows
//   - Prefill INT8: NOT AVAILABLE in IRON-windows
//
// We use a fixed array size of 3 (the max across active paths) and
// per-path kernel counts to loop only over valid slots.

// Slot indices — reused across paths where semantics overlap.
// Decode: FUSED=0 (gate+up+silu+mul), DOWN=1
// Prefill: GATE_UP=0, SILU_MUL=1, DOWN=2
enum xdna_swiglu_slot : int {
    XDNA_SWIGLU_SLOT_0      = 0,  // decode: fused gate+up+silu+mul | prefill: gemm_1 (gate/up)
    XDNA_SWIGLU_SLOT_1      = 1,  // decode: down GEMV              | prefill: silu_mul
    XDNA_SWIGLU_SLOT_2      = 2,  // decode: unused                 | prefill: gemm_2 (down)
    XDNA_SWIGLU_MAX_SLOTS   = 3,
};

// Per-path kernel counts.
static constexpr int XDNA_SWIGLU_DECODE_NUM_KERNELS = 2;
static constexpr int XDNA_SWIGLU_PREFILL_NUM_KERNELS = 3;
static constexpr int XDNA_SWIGLU_DECODE_INT4_NUM_KERNELS = 2;  // Phase 8.2

// Shorthand aliases for readability in dispatch code.
#define XDNA_SWIGLU_FUSED     XDNA_SWIGLU_SLOT_0  // decode fused kernel
#define XDNA_SWIGLU_DOWN      XDNA_SWIGLU_SLOT_1  // decode down GEMV
#define XDNA_SWIGLU_GATE_UP   XDNA_SWIGLU_SLOT_0  // prefill gate/up GEMM
#define XDNA_SWIGLU_SILU_MUL  XDNA_SWIGLU_SLOT_1  // prefill fused SiLU+Mul
#define XDNA_SWIGLU_DOWN_P    XDNA_SWIGLU_SLOT_2  // prefill down GEMM

// Legacy slot names — only used by INT8 dead code below.
// Wrapped in #if 0 since IRON-windows does not compile INT8 kernels.
#if 0
#define XDNA_SWIGLU_MATMUL_1  XDNA_SWIGLU_SLOT_0
#define XDNA_SWIGLU_MATMUL_2  XDNA_SWIGLU_SLOT_2
#define XDNA_SWIGLU_SILU      XDNA_SWIGLU_SLOT_1
#define XDNA_SWIGLU_ELTWISE   XDNA_SWIGLU_SLOT_1
#endif

// Kernel attribute names inside IRON-windows SwiGLU xclbin.
// Indexed by xdna_swiglu_slot; only [0..num_kernels-1] are valid per path.
static constexpr const char * XDNA_SWIGLU_DECODE_KERNEL_NAMES[XDNA_SWIGLU_MAX_SLOTS] = {
    "swiglu_fused",     // slot 0: fused gate+up dual-GEMV + SiLU + Mul
    "swiglu_gemv_2",    // slot 1: down projection GEMV
    nullptr,            // slot 2: unused for decode
};
static constexpr const char * XDNA_SWIGLU_PREFILL_KERNEL_NAMES[XDNA_SWIGLU_MAX_SLOTS] = {
    "swiglu_gemm_1",    // slot 0: gate/up GEMM
    "swiglu_silu_mul",  // slot 1: fused SiLU + element-wise Mul
    "swiglu_gemm_2",    // slot 2: down GEMM
};
// Phase 8.2: W4A16 SwiGLU decode -- 2 slots like bf16 decode but the kernel
// instance-names inside the xclbin carry the int4 suffix to disambiguate
// when the same hw_context loads both.
static constexpr const char * XDNA_SWIGLU_DECODE_INT4_KERNEL_NAMES[XDNA_SWIGLU_MAX_SLOTS] = {
    "swiglu_fused_int4",  // slot 0: dual_fused_dequant_gemv + silu + mul
    "swiglu_gemv_2_int4", // slot 1: fused_dequant_gemv for down
    nullptr,
};

// Per-slot insts filename tags (no "swiglu_" prefix). The bridge stages insts
// files as "<cache_dir>/swiglu_<tag>.insts".
static constexpr const char * XDNA_SWIGLU_DECODE_INSTS_TAGS[XDNA_SWIGLU_MAX_SLOTS] = {
    "fused", "gemv_2", nullptr,
};
static constexpr const char * XDNA_SWIGLU_PREFILL_INSTS_TAGS[XDNA_SWIGLU_MAX_SLOTS] = {
    "gemm_1", "silu_mul", "gemm_2",
};
// Phase 8.2: W4A16 SwiGLU decode -- same 2-slot structure as bf16 decode,
// just with int4 suffix on the tags to avoid colliding with bf16 .insts in the
// same hw_context.
static constexpr const char * XDNA_SWIGLU_DECODE_INT4_INSTS_TAGS[XDNA_SWIGLU_MAX_SLOTS] = {
    "fused_int4", "gemv_2_int4", nullptr,
};

struct xdna_swiglu_kernel_entry {
    xdna_op_kind    op_kind;  // XDNA_OP_SWIGLU_{DECODE,PREFILL}
    xrt::xclbin     xclbin;
    xrt::hw_context hw_ctx;
    xrt::kernel     kernels[XDNA_SWIGLU_MAX_SLOTS];
    int             num_kernels;  // actual kernel count for this path
    std::vector<char> insts_data[XDNA_SWIGLU_MAX_SLOTS];
    xrt::bo         insts_bo  [XDNA_SWIGLU_MAX_SLOTS];

    int64_t embedding_dim;
    int64_t hidden_dim;
    int64_t seq_len;  // 1 for decode, >=32 for prefill
    int     num_cols;
    // INT8-only: group_size baked into the compiled kernel (-DGROUP_SIZE) and
    // the clamped tile_size_input for each inner gemv stage. Unused for bf16
    // paths (left at their default-initialised zero values).
    int     group_size    = 0;
    int     mm1_m_input   = 0;  // gemv_int8_1 tile_size_input after L1-budget clamp
    int     mm2_m_input   = 0;  // gemv_int8_2 tile_size_input after L1-budget clamp

    // I/O BOs (lazy — allocated on first dispatch).
    // input_bo : embedding_dim * M bf16 (M=1 for decode)
    // output_bo: embedding_dim * M bf16
    //
    // These remain the canonical sync-path single-instance BOs (used by
    // bf16/INT8 SwiGLU paths). The INT4 SwiGLU async path (Phase 9) uses
    // the BO ring below instead.
    std::unique_ptr<xrt::bo> input_bo;
    std::unique_ptr<xrt::bo> output_bo;

    // Intermediate BOs (lazy). All are hidden_dim * M bf16.
    std::unique_ptr<xrt::bo> left_bo;          // matmul_1(w_gate, input)
    std::unique_ptr<xrt::bo> right_bo;         // matmul_1(w_up,   input)
    std::unique_ptr<xrt::bo> left_swished_bo;  // silu(left)
    std::unique_ptr<xrt::bo> intermediate_bo;  // eltwise_mul(left_swished, right)

    // Phase 9 INT4 SwiGLU async path: 3-BO ring per dispatch. The fused
    // gate+up+silu+mul stage reads slot's input_bo and writes its
    // intermediate_bo; the down GEMV stage reads intermediate_bo and
    // writes output_bo. Bias compensation for the down stage runs in
    // the deferred lambda. Ring back-pressure mirrors xdna_kernel_entry's
    // slot_active/slot_dst_data: when the dispatch picks next_slot, if
    // active, ctx->inflight.wait_for(slot_dst_data) runs the prior
    // dispatch's deferred (writing to dst) before reusing the slot.
    std::unique_ptr<xrt::bo> input_bo_ring[XDNA_PHASE9_RING_SIZE];
    std::unique_ptr<xrt::bo> intermediate_bo_ring[XDNA_PHASE9_RING_SIZE];
    std::unique_ptr<xrt::bo> output_bo_ring[XDNA_PHASE9_RING_SIZE];
    bool                     slot_active_swiglu[XDNA_PHASE9_RING_SIZE] = {};
    void *                   slot_dst_data_swiglu[XDNA_PHASE9_RING_SIZE] = {};
    int                      next_slot_swiglu = 0;

    // Weight BO caches — one map per slot (gate, up, down), keyed by the
    // ggml weight tensor's data pointer. Multi-layer models share a kernel
    // entry across layers (same shape ⇒ same cache key), so we need separate
    // BOs for each layer's weights. Mirrors xdna_kernel_entry::b_bo_cache.
    // For bf16 paths these hold bf16 transposed/native weights; for INT8
    // they hold packed uint8 byte buffers (interleaved int8 + bf16 scales).
    std::unordered_map<const void *, xrt::bo> w1_bo_cache;  // gate
    std::unordered_map<const void *, xrt::bo> w2_bo_cache;  // up
    std::unordered_map<const void *, xrt::bo> w3_bo_cache;  // down

    // Fused gate+up weight BO cache for decode DualGEMVSiLUMul kernel.
    // Keyed by a combined 64-bit hash of both source data pointers.
    std::unordered_map<uint64_t, xrt::bo> w_fused_bo_cache;

    std::unique_ptr<std::mutex> weights_mutex = std::make_unique<std::mutex>();
};

// ============================================================================
// Fused INT8 SwiGLU entry — single combined xclbin with 2 kernel entries
// (fused gate+up+silu+mul + down GEMV), dispatched via xrt::runlist.
// ============================================================================

struct xdna_swiglu_fused_entry {
    xdna_op_kind  op_kind;  // always XDNA_OP_SWIGLU_FUSED_INT8

    // Single combined xclbin with 2 kernel entries.
    xrt::xclbin     xclbin;
    xrt::hw_context hw_ctx;
    xrt::kernel     fused_kernel;   // gate+up+silu+mul
    xrt::kernel     down_kernel;    // standalone down GEMV

    // Per-kernel insts data + BOs.
    std::vector<char> fused_insts_data;
    xrt::bo         fused_insts_bo;
    std::vector<char> down_insts_data;
    xrt::bo         down_insts_bo;

    int64_t embedding_dim;
    int64_t hidden_dim;
    int     num_cols;
    int     group_size;
    int     fused_m_input;  // clamped tile_size_input for gate/up (fused kernel)
    int     down_m_input;   // clamped tile_size_input for down GEMV

    // I/O BOs (lazy — allocated on first dispatch).
    std::unique_ptr<xrt::bo> input_bo;         // embedding_dim bf16
    std::unique_ptr<xrt::bo> intermediate_bo;  // hidden_dim bf16
    std::unique_ptr<xrt::bo> output_bo;        // embedding_dim bf16

    // Weight BO caches — one map per slot, keyed by ggml weight tensor data ptr.
    std::unordered_map<const void *, xrt::bo> w_gate_bo_cache;
    std::unordered_map<const void *, xrt::bo> w_up_bo_cache;
    std::unordered_map<const void *, xrt::bo> w_down_bo_cache;

    std::unique_ptr<std::mutex> weights_mutex = std::make_unique<std::mutex>();
};

// ============================================================================
// Fused QKV projection entry — single combined xclbin with 1 fused kernel
// (fused_qkv GEMV), dispatched via a single xrt::run.
// Weights Wq, Wk, Wv are concatenated row-wise into one matrix on host.
// ============================================================================

struct xdna_qkv_entry {
    xdna_op_kind  op_kind;  // always XDNA_OP_QKV

    xrt::xclbin     xclbin;
    xrt::hw_context hw_ctx;
    xrt::kernel     fused_kernel;     // single fused_qkv GEMV

    std::vector<char> insts_data;     // qkv_main.insts
    xrt::bo           insts_bo;

    int64_t embedding_dim;
    int64_t q_dim, k_dim, v_dim;
    int64_t total_out;   // q_dim + k_dim + v_dim
    int     num_cols;

    // I/O BOs (lazy)
    std::unique_ptr<xrt::bo> input_bo;      // embedding_dim bf16
    std::unique_ptr<xrt::bo> output_bo;     // total_out bf16

    // Weight BO cache — keyed by Q weight ptr (assumes q/k/v change together).
    std::unordered_map<const void *, xrt::bo> w_concat_bo_cache;

    std::unique_ptr<std::mutex> weights_mutex = std::make_unique<std::mutex>();
};

// ============================================================================
// Attention-prefill chained entry — 11 sub-kernels in one combined.xclbin.
// Mirrors iron/operators/attention_block_prefill/op.py AttentionBlockPrefill.
// Kernel names inside the xclbin are "attn_prefill_<slot>"; insts files are
// staged at "<bundle_dir>/attn_prefill_<slot>.insts".
// ============================================================================

enum xdna_attn_prefill_slot : int {
    XDNA_ATTN_RMS_NORM = 0,
    XDNA_ATTN_GEMM_Q   = 1,
    XDNA_ATTN_GEMM_KV  = 2,  // shared by K and V projections
    XDNA_ATTN_ROPE_Q   = 3,
    XDNA_ATTN_ROPE_K   = 4,
    XDNA_ATTN_PERM_Q   = 5,
    XDNA_ATTN_PERM_KV  = 6,  // shared by K and V permutations
    XDNA_ATTN_MHA      = 7,
    XDNA_ATTN_PERM_O   = 8,
    XDNA_ATTN_GEMM_O   = 9,
    XDNA_ATTN_ADD      = 10,
    XDNA_ATTN_NUM_SLOTS = 11,
};

static constexpr const char * XDNA_ATTN_PREFILL_KERNEL_NAMES[XDNA_ATTN_NUM_SLOTS] = {
    "attn_prefill_rms_norm",
    "attn_prefill_gemm_q",
    "attn_prefill_gemm_kv",
    "attn_prefill_rope_q",
    "attn_prefill_rope_k",
    "attn_prefill_perm_q",
    "attn_prefill_perm_kv",
    "attn_prefill_mha",
    "attn_prefill_perm_o",
    "attn_prefill_gemm_o",
    "attn_prefill_add",
};

static constexpr const char * XDNA_ATTN_PREFILL_INSTS_TAGS[XDNA_ATTN_NUM_SLOTS] = {
    "rms_norm", "gemm_q", "gemm_kv", "rope_q", "rope_k",
    "perm_q",   "perm_kv","mha",    "perm_o", "gemm_o", "add",
};

struct xdna_attention_prefill_entry {
    xdna_op_kind    op_kind;  // always XDNA_OP_ATTENTION_PREFILL

    xrt::xclbin     xclbin;
    xrt::hw_context hw_ctx;
    xrt::kernel     kernels[XDNA_ATTN_NUM_SLOTS];
    std::vector<char> insts_data[XDNA_ATTN_NUM_SLOTS];
    xrt::bo         insts_bo  [XDNA_ATTN_NUM_SLOTS];

    // Shape params (baked into the xclbin).
    int64_t seq_len_padded;
    int64_t embed_dim;
    int64_t num_heads;
    int64_t num_kv_heads;
    int64_t head_dim;

    std::string cache_key;

    // Per-call persistent BOs (lazy, allocated on first dispatch).
    //   bo_x_in    : (seq*embed) bf16 — residual input, also fed to RMSNorm
    //   bo_x_norm  : (seq*embed) bf16 — RMSNorm output
    //   bo_q_proj  : (seq*H*d)   bf16 — GEMM_Q output (pre-RoPE)
    //   bo_k_proj  : (seq*KV*d)  bf16 — GEMM_KV(K) output
    //   bo_v_proj  : (seq*KV*d)  bf16 — GEMM_KV(V) output
    //   bo_q_rope  : (seq*H*d)   bf16 — RoPE(Q)
    //   bo_k_rope  : (seq*KV*d)  bf16 — RoPE(K)
    //   bo_q_perm  : (H*seq_pad*d) bf16  (MHA's Q/K/V all share this buffer size)
    //   bo_k_perm  : (H*seq_pad*d) bf16  (oversized to match MHA's arg_spec)
    //   bo_v_perm  : (H*seq_pad*d) bf16  (ditto)
    //   bo_attn_out: (H*seq_pad*d) bf16 — MHA output
    //   bo_o_perm  : (seq*H*d)   bf16 — perm_o output (seq,H,d)
    //   bo_o_proj  : (seq*embed) bf16 — GEMM_O output
    //   bo_output  : (seq*embed) bf16 — residual ADD output (final)
    //   bo_gain    : (embed)     bf16 — RMSNorm gain (per-layer, repacked-cached)
    //   bo_angles  : (seq*d)     bf16 — RoPE cos/sin LUT (per-dispatch, positions vary)
    std::unique_ptr<xrt::bo> bo_x_in;
    std::unique_ptr<xrt::bo> bo_x_norm;
    std::unique_ptr<xrt::bo> bo_q_proj;
    std::unique_ptr<xrt::bo> bo_k_proj;
    std::unique_ptr<xrt::bo> bo_v_proj;
    std::unique_ptr<xrt::bo> bo_q_rope;
    std::unique_ptr<xrt::bo> bo_k_rope;
    std::unique_ptr<xrt::bo> bo_q_perm;
    std::unique_ptr<xrt::bo> bo_k_perm;
    std::unique_ptr<xrt::bo> bo_v_perm;
    std::unique_ptr<xrt::bo> bo_attn_out;
    std::unique_ptr<xrt::bo> bo_o_perm;
    std::unique_ptr<xrt::bo> bo_o_proj;
    std::unique_ptr<xrt::bo> bo_output;
    std::unique_ptr<xrt::bo> bo_angles;

    // Per-layer weight / gain BOs, cached by source ggml tensor data pointer.
    // w_q/w_k/w_v/w_o hold bf16 transposed [K,N] layouts (GEMM B-buffer);
    // gain holds bf16 row of size embed_dim.
    std::unordered_map<const void *, xrt::bo> w_q_bo_cache;
    std::unordered_map<const void *, xrt::bo> w_k_bo_cache;
    std::unordered_map<const void *, xrt::bo> w_v_bo_cache;
    std::unordered_map<const void *, xrt::bo> w_o_bo_cache;
    std::unordered_map<const void *, xrt::bo> gain_bo_cache;

    std::unique_ptr<std::mutex> weights_mutex = std::make_unique<std::mutex>();
};

